# [doc = " A single command entry captured by the shell plugin."] # [derive (Debug , Clone , PartialEq , Eq , serde :: Serialize , serde :: Deserialize)] pub struct TerminalCommand { # [doc = " The command text as entered by the user."] pub command : String , # [doc = " The exit code produced by the command."] pub exit_code : i32 , # [doc = " Unix timestamp (seconds since epoch) when the command was run."] pub timestamp : u64 , }